# ---- Joseph's rulings of 27 Nov (answers to A4 Q1, Q2, Q4)
QT='Rubr. gen. XI.2 (M39 p. 52): "si in fine Orationis fiat ejus mentio, terminatur per Qui tecum vivit"; Joseph (27 Nov): follow the printed pointing "Fílium tuum; qui tecum" (\';\' = flexa, Proc. 1913 p. 405); the Missal prints no comma after "Christum"'
for k,p,pg in [('G494','or','M39 p. 472 (pdf 275)'),('G494','pc','M39 p. 473 (pdf 275)'),('S0624','se','M39 p. 475 (pdf 276)'),('S0624','pc','M39 p. 475 (pdf 276)')]:
    SUB('data/orations.js',[k,p,0],[('Iesum Christum, Fílium tuum: qui tecum','Iesum Christum Fílium tuum; qui tecum')],pg,'printed "Dóminum nostrum Jesum Christum Fílium tuum; qui tecum." '+QT)
def ADD(file,path,new,src,why): FX.append({"file":file,"op":"add","path":path,"old":None,"new":new,"src":src,"why":why})
# Q2: votive per annum variants (Joseph: every proper the Missal prints must be on the site)
V492='M39 p. 492 (pdf 285): "Quando celebratur de SS. Joanne et sociis ex voto vel devotione per annum, Officium erit ut supra, excepto Credo." Temp. Pasch. Alleluia V. Repleti sumus; Alleluia V. In die resurrectionis; Temp. Ascens. secundum Alleluia V. Ascendens'
ADD('data/masses.js',['masses','S0709','season','pasch'],{"al":[{"id":6183,"m39":"p. 492"},{"id":5632,"m39":"p. 492","v50":"G50 p. 211"}]},'M39 p. 492 (pdf 285)',V492+'; two verses with four Alleluias in Paschaltide, Rubr. gen. XIII.1 (p. 53)')
ADD('data/masses.js',['masses','S0709','season','asc'],{"al":[{"id":6183,"m39":"p. 492"},{"id":5526,"m39":"p. 492"}]},'M39 p. 492 (pdf 285)',V492)
V503='M39 p. 503 (pdf 290): "Quando per anni circulum celebratur de S. Maria Magdalena ex voto, vel devotione: Officium Ps. 44 Dilexisti ... T. P. Alleluia, alleluia ... Reliqua dicuntur ut supra, excepto Credo. Tempore Resurrectionis, vel Ascensionis, Alleluia, et infra Septuagesimam, Tract. Veni, ut in Communi, p. 37*"; p. 37* (pdf 386): Alleluia V. Veni electa; Tempore Resurr. secundum Alleluia V. Surrexit Dominus et occurrens; Tempore Ascens. secundum Alleluia V. Ascendens; Infra Septuag. Tractus Veni sponsa Christi'
FX.append({"file":"data/masses.js","path":['masses','S0722','season','pasch'],"old":{"al":[{"id":5130}]},"new":{"in":[{"id":5384,"m39":"p. 503"}],"al":[{"id":5685,"m39":"p. 37*"},{"id":5130,"m39":"p. 37*"}]},"src":"M39 p. 503, p. 37* (pdf 290, 386)","why":V503+'; the feast (22 July) never falls in Paschaltide, so this set serves only the votive Mass; two verses in Paschaltide, Rubr. gen. XIII.1 (p. 53)'})
ADD('data/masses.js',['masses','S0722','season','asc'],{"al":[{"id":5685,"m39":"p. 37*"},{"id":5526,"m39":"p. 37*"}]},'M39 p. 503, p. 37* (pdf 290, 386)',V503)
ADD('data/masses.js',['masses','S0722','season','lent'],{"tr":[{"id":6032,"m39":"p. 37*"}]},'M39 p. 503, p. 37* (pdf 290, 386)',V503+'. NOTE: the votive Introit Dilexisti outside Paschaltide (per annum, infra Septuag.) cannot be expressed by the season sets; app.js needs a votive form')
# Q4: Gaudeamus with the name: the Missal's text, no adapted notation
G4='Joseph (27 Nov): print the Missal\'s text with the name; notated chant only where a Dominican book prints the melody with that name, never adapted. No Dominican source (GregoBase 11-14, 20, 21, 35, 36) prints this Gaudeamus with this name (only 4288-4292: Omnium Sanctorum, Nativitate, Coronae, beatae N. Virginis, Francisci). app.js must show this text, unnotated, in place of the gabc'
GT=lambda nm,de: 'Gaudeámus omnes in Dómino, diem festum celebrántes sub honóre '+nm+' de cujus '+de+' gaudent Angeli, et colláudant Fílium Dei. ℣. Ps. 44 Eructávit cor meum verbum bonum: dico ego ópera mea regi. Glória Patri.'
for k,nm,de,pg in [('S0702','beátæ Maríæ Vírginis,','Visitatióne','M39 p. 485 (pdf 281)'),('S0716','beátæ Maríæ Vírginis,','solemnitáte','M39 p. 497 "Officium Gaudeamus, ut in Festis B. Mariae Virginis, pag. 1*"; p. 1* (pdf 368)'),('S0722','beátæ Maríæ Magdalénæ,','solemnitáte','M39 p. 502 (pdf 290)'),('S0726','beátæ Annæ','solemnitáte','M39 p. 506 "Officium Gaudeamus, ut in Comm. nec Virg. nec Mart., pag. 36*"; p. 36* (pdf 386) prints "beátæ N. de cujus solemnitáte"'),('S0729','beátæ Marthæ Vírginis,','solemnitáte','M39 p. 508 (pdf 293)')]:
    ADD('data/masses.js',['masses',k,'parts','in',0,'m39text'],GT(nm,de),pg,G4)
